export const DATA_06: ReadingTest[] = [
  { id: "rd-006", num: 6, title: "Đề 006", timeMin: 60, parts: [
    { title: "Li Ziqi and the Rise of Traditional Lifestyle Videos", paragraphs: ["Li Ziqi is a Chinese video creator. She became famous for showing a quiet, traditional way of life in the countryside. Her videos usually show her cooking meals, growing vegetables, or making simple household items using old methods passed down through generations. There is rarely any talking in her videos, only the natural sounds of nature, cooking, or tools being used. This calm, simple style helped her stand out from most other online creators, who often rely on fast editing and constant talking to hold attention.", "Each video usually follows the same relaxed pattern from start to finish. Li Ziqi might be planting rice, weaving cloth, or preparing a seasonal dish from ingredients she grew herself in her own garden. The scenery in her videos is often stunning, showing green mountains, quiet rivers, and small wooden houses that feel far removed from busy city life. Viewers often say that watching her videos feels like taking a short, peaceful break from their normal daily routine. Some people even leave her videos playing quietly in the background simply to relax while working or studying at home.", "Li Ziqi first became popular on Chinese platforms. Her videos then slowly spread to international sites, where she gained an enormous global audience. Remarkably , most of her international viewers do not understand Chinese and rely entirely on the visuals to follow along. Her channel eventually earned major awards and set records for the most subscribers on a Chinese-language channel, a surprising achievement given how few words she actually speaks. News outlets in many countries wrote articles about her, calling her one of the most influential creators of her generation.", "Her success encouraged many other creators around the world to try a similar style. Today, plenty of channels now focus on slow living, traditional cooking, or rural life, clearly inspired by the format Li Ziqi helped make popular across so many different countries. Some creators live on small farms and film their daily chores, while others focus mainly on cooking traditional recipes from scratch using local ingredients. This growing trend shows how one creator's simple videos can shape an entire genre of online content, even reaching audiences who once had little interest in this kind of quiet, slow-paced video.", "Experts who study online media suggest that her appeal comes from offering an escape from the stress of modern, fast-paced life. Many viewers spend their days looking at screens filled with notifications. Watching someone quietly cook a meal or fix an old wooden chair feels unusually restful by comparison. Whether or not this trend continues to grow, Li Ziqi's videos have already shown that calm, simple content can attract a massive worldwide audience, even without a single word of dialogue."], questions: [{ q: "What is the passage mainly about?", options: ["The specific cooking techniques Li Ziqi uses in videos", "The reasons why most online creators fail to gain viewers today", "Li Ziqi became famous for calm videos that inspired a new genre", "How every Chinese video creator eventually becomes world-famous overall"], answer: 2 }, { q: "According to the passage, what is unusual about Li Ziqi's videos?", options: ["Her videos rarely include talking, only natural sounds of daily life", "Her videos always include talking to explain every single step clearly fully", "Her videos include background music instead of natural sounds", "Her videos use fast editing and constant talking to hold"], answer: 0 }, { q: "According to the passage, what is true about most of Li Ziqi's international viewers?", options: ["Most international viewers understand Chinese fluently before watching videos closely", "Most international viewers first learn Chinese from watching her videos closely", "Most international viewers need subtitles translated into many different spoken languages today", "Most international viewers do not understand Chinese at all"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as something Li Ziqi does in her videos?", options: ["Growing vegetables and preparing seasonal dishes from scratch", "Winning a major international singing competition held for young musicians annually", "Making household items using old traditional methods passed down carefully", "Weaving cloth and planting rice in the countryside"], answer: 1 }, { q: "According to the passage, why do experts think Li Ziqi's videos appeal to many viewers?", options: ["Watching her calm videos offers a restful escape from busy life", "Watching her videos teaches viewers professional traditional cooking skills quickly", "Her videos appeal to viewers because they contain fast-paced action", "Her videos appeal only to viewers who already live in the countryside"], answer: 0 }, { q: "The word \"remarkably\" in paragraph 3 is closest in meaning to _______.", options: ["slightly", "secretly", "surprisingly", "eventually"], answer: 2 }, { q: "The word \"enormous\" in paragraph 3 is closest in meaning to _______.", options: ["huge", "tiny", "average", "distant"], answer: 0 }, { q: "The word \"who\" in paragraph 4 refers to _______.", options: ["other video creators", "traditional recipes", "small farms", "some new viewers"], answer: 3 }, { q: "What can be inferred from paragraph 4 about the future of this video style?", options: ["Li Ziqi will soon stop making videos completely now", "More creators will likely keep copying her calm, slow style", "Fast-paced videos will completely disappear from the whole internet entirely very soon", "Every viewer who watches her videos will move to the countryside"], answer: 1 }, { q: "What is the author's main purpose in writing this passage?", options: ["To teach readers specific traditional Chinese cooking techniques step by step fully", "To criticize modern viewers for watching too many online", "To explain why Li Ziqi's calm videos became so popular", "To argue that every creator should copy her exact video"], answer: 2 }] },
    { title: "The Growth of Digital Tourism: Virtual Experiences, Real Consequences", paragraphs: ["Long before a traveler books a flight, many now visit a destination first through a screen. Virtual tours, livestreamed walks through crowded markets, and drone footage of remote landscapes have turned digital tourism into something considerably more influential than a simple marketing tool. What began as a way for museums and tourism boards to reach wider audiences has evolved into a genuine substitute for travel itself, one that shapes expectations long before, and sometimes instead of, an actual visit to the place in question.", "For many people, this shift represents a meaningful expansion of access rather than a mere novelty . Viewers with limited mobility, tight budgets, or restrictive travel documents can now experience the Louvre's corridors or Antarctica's ice shelves without leaving their living rooms at all. Some tourism boards have reported that virtual previews increase eventual bookings rather than replacing them entirely, suggesting that digital access may function as a gateway experience for at least a portion of viewers rather than a final substitute for the journey itself.", "Other evidence, however, considerably complicates that otherwise reassuring picture of expanding access to distant places. Surveys of younger travelers in several countries have found a growing minority who say a sufficiently immersive virtual experience would satisfy their curiosity about a place. Whether this sentiment will meaningfully reduce real-world travel demand remains genuinely uncertain for now. Even so, tourism boards in a handful of heavily visited destinations have begun treating the possibility seriously enough to fund their own virtual offerings as a precautionary measure.", "Even where virtual tourism has not reduced physical visits, it has altered how host communities are perceived and treated by outsiders. Locations popularized primarily through short viral clips often experience visitor surges disproportionate to their physical capacity. A striking image can travel far faster than any accompanying context about fragility or local customs, after all. Residents in several such locations have described feeling reduced to a photogenic backdrop, valued chiefly for how well their neighborhood photographs rather than for anything else about daily life there.", "The economic picture accompanying this shift is similarly divided in important ways worth examining closely. Digital previews can generate revenue directly, through paid virtual tours or platform advertising. This income requires no additional strain on local infrastructure or environment, at least in principle. Yet critics note that this same convenience may undercut the case for costlier, more comprehensive protections. A destination that is already earning steady income virtually may have comparatively weaker incentive to limit the physical crowding that its own growing popularity eventually produces on the ground.", "None of this suggests that digital tourism is simply good or bad for the places it depicts. A single clear verdict is not really possible yet, in truth. What the accumulated evidence instead indicates is that virtual and physical tourism have become genuinely intertwined in ways few observers anticipated at the outset. Each now shapes demand, expectation, and consequence for the other in ways neither tourism boards nor host communities fully anticipated when the technology first appeared on a wide scale across the industry."], questions: [{ q: "What is the passage mainly about?", options: ["The specific ways virtual museum tours increase paid bookings", "The purely negative effects virtual tourism has caused for communities", "Digital tourism now reshapes real-world travel demand and its consequences broadly today", "How virtual tourism has completely replaced physical travel for most people"], answer: 2 }, { q: "According to the passage, what is suggested about the relationship between virtual previews and bookings?", options: ["Virtual previews may increase eventual bookings rather than simply replacing them", "Virtual previews always increase bookings for every viewer without any exception", "Virtual previews increase bookings only because they eliminate long-haul flights entirely now", "Virtual previews increase bookings solely among past visitors only"], answer: 0 }, { q: "According to the passage, what have surveys found about younger travelers?", options: ["The majority of younger travelers now say virtual experience fully replaces travel", "Only travelers over sixty say virtual experience could ever satisfy curiosity", "Tourism boards themselves say virtual experience fully satisfies their curiosity", "A growing minority of younger travelers say virtual experience"], answer: 3 }, { q: "According to paragraphs 4 and 5, what may happen when a location becomes popular through viral content?", options: ["Visitor surges occur only because boards deliberately encourage overcrowding for profit", "Viral popularity can cause surges beyond a location's capacity limits", "Every location in a viral video suffers permanent, irreversible environmental damage always", "Virtual popularity always increases a destination's incentive to limit crowding immediately"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a consequence for host communities?", options: ["Visitor surges disproportionate to a location's physical capacity", "Residents feeling reduced to a photogenic backdrop only", "Local governments banning all tourism completely and permanently", "Being valued chiefly for how well a neighborhood photographs"], answer: 2 }, { q: "The word \"novelty\" in paragraph 2 is closest in meaning to _______.", options: ["fad", "tradition", "failure", "routine"], answer: 0 }, { q: "The word \"disproportionate\" in paragraph 4 is closest in meaning to _______.", options: ["minimal", "predictable", "seasonal", "excessive"], answer: 3 }, { q: "The word \"Each\" in paragraph 6 refers to _______.", options: ["tourism boards worldwide", "virtual and physical tourism", "host communities alone", "demand and expectation"], answer: 1 }, { q: "What can be inferred by connecting paragraphs 4 and 5?", options: ["Virtual tourism revenue will eventually replace all physical tourism income soon entirely", "Physical overcrowding causes destinations to invest in virtual revenue streams", "Destinations earning virtual revenue may feel less pressure to fix crowding", "Digital previews generate revenue without any local strain whatsoever"], answer: 2 }, { q: "What is the author's main purpose in writing this passage?", options: ["To show how virtual and physical tourism have become mutually influential overall", "To detail specific economic benefits virtual tours provide to museums", "To condemn virtual tourism entirely as harmful to communities", "To predict that virtual tourism will soon fully replace physical travel"], answer: 0 }] },
    { title: "The History and Influence of Public Libraries", paragraphs: ["Institutions resembling libraries have existed for millennia, from the scroll collections of ancient Alexandria to the monastic archives of medieval Europe. Yet the public library as a freely accessible civic institution is a considerably more recent invention. Its emergence tracks closely with the broader nineteenth-century push to extend literacy and education beyond a narrow elite. That particular timing was no mere coincidence at all, historians generally agree, but rather a direct consequence of industrialization's growing demand for an increasingly literate national workforce.", "Much of the movement's early momentum in English-speaking countries came from private philanthropy rather than government initiative. Industrialists such as Andrew Carnegie funded thousands of library buildings across multiple continents, on the condition that local governments commit to ongoing operating costs. This arrangement was undeniably effective at rapidly expanding the physical network of libraries worldwide. It has, however, left later historians divided over how much credit belongs to individual philanthropy versus the communities that sustained these institutions for generations afterward.", "Public libraries were never meant simply to lend books to patrons. From the outset, they were conceived as engines of civic education and social mobility. Proponents argued, and many still argue, that unrestricted access to information could narrow the gap between social classes more effectively than most other public interventions. Measuring this claim rigorously has proven difficult, however, since library usage correlates with numerous other factors, including household income and prior educational attainment, that independently predict social mobility regardless of library access.", "Few institutions have faced more persistent predictions of obsolescence than the public library. This is particularly true since the widespread arrival of internet access in private homes. If information is now available instantly and free of charge online, the reasoning goes, then a physical building organized around lending printed books has lost its original justification. This argument, though intuitively appealing, has generally failed to anticipate how libraries themselves would adapt to the same technological shift presumed to be making them irrelevant.", "Rather than resisting digital transformation, many public libraries repositioned themselves as essential access points. This served populations without reliable home internet or computer equipment of their own. Job seekers now complete online applications at library terminals, and library-issued hotspots let households without broadband service connect from home. This adaptation, while widely praised by policy researchers, has arguably shifted the institution's core function from book lending toward something closer to a general-purpose social service, a transformation not everyone within the profession has welcomed.", "Whether this expanded role justifies continued public funding remains a genuinely contested question among policymakers. Critics argue that dedicated digital-equity programs could serve the same population more efficiently than maintaining an extensive network of physical buildings. Defenders counter that libraries provide something these narrower programs cannot replicate. It is a physically shared, non-commercial civic space that requires no purchase, membership, or justification to enter, a function some researchers consider increasingly scarce in modern urban life.", "None of this suggests that the public library's future is secure by default. Nor does it support the periodic predictions of its imminent disappearance that keep resurfacing every decade. What the accumulated evidence instead indicates is that the institution's survival depends less on any inherent, timeless value than on each generation's willingness to keep redefining what a shared civic space is actually for."], questions: [{ q: "What is the passage mainly about?", options: ["The specific architectural styles used in early Carnegie library", "The clear reasons why public libraries will soon disappear completely", "Public libraries' survival depends on each generation redefining their civic purpose today", "How every library worldwide eventually adopted identical digital access programs"], answer: 2 }, { q: "According to the passage, under what condition did Carnegie fund library buildings?", options: ["Carnegie funded buildings if local governments paid ongoing operating costs", "Carnegie funded buildings only after local governments fully repaid his investment", "Carnegie personally paid all ongoing operating costs for every single library built", "Carnegie funded buildings without requiring any government involvement whatsoever"], answer: 0 }, { q: "According to the passage, what makes the claim about libraries and social mobility hard to verify?", options: ["Library access has been proven to directly cause all mobility", "Household income alone fully explains every case of social mobility observed", "Library usage and social mobility share absolutely no meaningful statistical relationship today", "Library access alone cannot be proven to cause mobility"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a service libraries now provide?", options: ["Job seekers completing online applications using library computer terminals", "A complete nationwide ban on printed books in every public library", "Households borrowing library-issued hotspots to connect without home broadband service", "Libraries functioning as a general-purpose social service beyond simple book lending"], answer: 1 }, { q: "According to the passage, what do critics argue about digital-equity programs?", options: ["Critics argue digital-equity programs have already fully replaced all libraries", "Critics argue digital-equity programs work only in wealthy urban areas today", "Critics argue digital-equity programs could serve the population more efficiently", "Critics argue digital-equity programs exist only because libraries refused digital adoption"], answer: 2 }, { q: "The word \"obsolescence\" in paragraph 4 is closest in meaning to _______.", options: ["outdatedness", "novelty", "expansion", "affordability"], answer: 0 }, { q: "The word \"scarce\" in paragraph 6 is closest in meaning to _______.", options: ["abundant", "expensive", "predictable", "rare"], answer: 3 }, { q: "The word \"It\" in paragraph 6 refers to _______.", options: ["a digital-equity program", "a shared civic space", "a Carnegie library building", "a household broadband service"], answer: 1 }, { q: "What can be inferred by connecting paragraphs 4 and 7?", options: ["Public libraries will inevitably close within the next decade completely for good", "Digital-equity programs will soon fully replace every library worldwide", "Whether libraries survive may depend more on adaptability than tradition", "Carnegie's original funding model alone explains today's library funding debates fully"], answer: 2 }, { q: "What is the author's main purpose in writing this passage?", options: ["To complicate common assumptions about whether libraries remain fully relevant today", "To detail the specific architecture of early Carnegie-funded library", "To argue that public libraries should lose all government funding", "To celebrate how perfectly libraries have adapted to digital technology overall today"], answer: 0 }] },
    { title: "Artificial Intelligence and Human Decision-Making: Augmentation, Delegation, and the Erosion of Judgement", paragraphs: ["As algorithmic systems increasingly mediate decisions once made entirely by human judgment, from loan approvals to medical diagnoses, a genuinely difficult question has emerged. That question is more unsettling than whether these systems are merely accurate in their outputs. It concerns what happens to human decision-making capacity itself when it is gradually relieved of the very friction that once forced deliberation, doubt, and the weighing of competing considerations.", "Proponents of AI-assisted decision-making generally frame the technology as augmentation rather than replacement. It is a tool that handles routine pattern recognition, they argue, so that human judgment can focus on genuinely novel or ethically complex cases. Some evidence supports this framing. Physicians using diagnostic aids reportedly catch rare conditions they might otherwise miss, freeing cognitive resources for the harder work of communicating difficult news and weighing patient-specific context that no algorithm currently captures.", "Other evidence complicates this optimistic account considerably. Studies of professionals across several fields have found something troubling about long-term reliance on algorithmic tools. Over time, such reliance can erode the very judgment the technology was meant to merely support, and radiologists who grow accustomed to software flagging abnormalities reportedly become measurably slower at detecting those same abnormalities unaided. This pattern suggests that some cognitive capacities may function less like fixed skills and more like muscles that atrophy without regular, unassisted use.", "Few phenomena illustrate this risk more clearly than automation bias. This is the well-documented tendency to defer to algorithmic output even when contrary evidence is directly available. Pilots have followed clearly malfunctioning autopilot systems well past the point at which manual instruments indicated an obvious problem, and clinicians have reportedly accepted algorithmically flagged diagnoses that contradicted findings from their own physical examination. The bias appears strongest precisely among the most experienced practitioners, who may have the most cognitive capacity to spare for oversight yet frequently exercise it least.", "Part of what sustains this pattern is structural rather than purely psychological in nature. Institutions that deploy decision-support systems often measure success partly through throughput, and querying an algorithm's judgment takes time that reviewing it uncritically does not require. Workers operating under this kind of institutional pressure may rationally choose to defer, even when they retain the underlying capacity to catch an error, because the personal cost of slowing down consistently exceeds the personal cost of an occasional, difficult-to-trace mistake.", "Whether these dynamics ultimately produce worse decisions on net remains genuinely disputed among researchers studying this question closely. Some studies find that human-algorithm teams outperform either humans or algorithms working alone, particularly on tasks combining pattern recognition with contextual judgment. Other researchers counter that these apparent gains largely reflect the algorithm doing most of the cognitive work, with human involvement functioning mainly as after-the-fact legitimation rather than meaningful independent oversight. That distinction is one the aggregate performance statistics alone cannot settle.", "None of this implies that algorithmic decision support is inherently corrosive to human judgment in every context. Nor does it vindicate uncritical enthusiasm for delegating consequential decisions to automated systems without oversight. What the accumulated evidence instead suggests is that whether augmentation or erosion predominates depends substantially on how institutions structure the incentives surrounding human oversight, a structural choice too often treated as an afterthought. That afterthought, this passage has argued, actually deserves to be the central question all along."], questions: [{ q: "What is the passage mainly about?", options: ["The specific medical conditions radiologists most commonly miss today", "The clear proof that algorithms always outperform human professionals alone", "Whether AI erodes or strengthens judgment depends on institutional design choices made", "How every profession will soon fully delegate decisions to algorithms"], answer: 2 }, { q: "According to the passage, what does some evidence suggest about diagnostic aids?", options: ["Diagnostic aids may help physicians catch rare conditions they might miss", "Diagnostic aids always catch every rare condition with complete certainty", "Diagnostic aids only help physicians because they eliminate all communication entirely completely", "Diagnostic aids help solely physicians who specialize in rare diseases"], answer: 0 }, { q: "According to the passage, what has been found about radiologists who rely on flagging software?", options: ["Radiologists have already become completely and permanently incapable of unaided diagnosis forever", "Radiologists grow slower only because software itself damages their eyesight", "Radiologists using software aids always diagnose faster than those unaided today", "Radiologists may grow measurably slower without regular, unassisted practice"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as part of automation bias?", options: ["Pilots following malfunctioning autopilot past clear manual instrument warnings", "Automation bias being completely eliminated among every single experienced practitioner without exception", "Clinicians accepting flagged diagnoses contradicting their own physical examination findings", "The bias appearing strongest among practitioners with the most spare capacity"], answer: 1 }, { q: "According to the passage, why might workers rationally choose to defer to an algorithm?", options: ["Deferring is always irrational no matter the institutional pressure", "Institutions always reward workers who slow down to review carefully fully", "Deferring may be rational when slowing down costs more personally", "Workers defer only because they have completely lost the underlying capacity entirely"], answer: 2 }, { q: "The word \"atrophy\" in paragraph 3 is closest in meaning to _______.", options: ["weaken", "strengthen", "expand", "stabilize"], answer: 0 }, { q: "The word \"corrosive\" in paragraph 7 is closest in meaning to _______.", options: ["beneficial", "irrelevant", "temporary", "damaging"], answer: 3 }, { q: "The word \"This\" in paragraph 3 refers to _______.", options: ["the diagnostic aid itself", "the radiologist slowdown effect", "patient-specific context", "automation bias generally"], answer: 1 }, { q: "What can be inferred by connecting paragraphs 5 and 7?", options: ["Algorithmic decision support will inevitably replace all human judgment", "Human-algorithm teams always outperform humans or algorithms working completely alone", "Institutional incentive design may matter more than the technology alone itself", "Automation bias occurs only among the least experienced practitioners in every field"], answer: 2 }, { q: "What is the author's main purpose in writing this passage?", options: ["To show that AI's effect on judgment depends on design", "To detail the specific software radiologists use for diagnosis", "To argue that algorithmic decision support should be banned entirely now", "To predict precisely when algorithms will fully replace all human judgment completely"], answer: 0 }] },
  ] },
  { id: "rd-181", num: 181, title: "Đề 181", timeMin: 60, parts: [
    { title: "The Cyclo: A Vanishing Icon of Vietnamese Streets", paragraphs: ["The cyclo, a three-wheeled bicycle taxi with a wide passenger seat mounted at the front, has long been one of the most recognizable sights on Vietnamese streets. Unlike a rickshaw, which a driver pulls from in front, the cyclo is pedaled from behind, allowing the rider to sit forward and enjoy an unobstructed view. The vehicle first appeared in Vietnam during the 1930s, introduced under French colonial rule, and it quickly spread through the country's growing cities. Hanoi and Saigon, now known as Ho Chi Minh City, became the two places where cyclos were most common, weaving through narrow streets that cars could not easily enter.", "For much of the twentieth century, the cyclo served as an essential part of everyday urban life rather than simply a novelty . It was cheap, and its small size let it slip down alleys that buses and cars found impossible to navigate. Many families relied on a single cyclo to carry not only passengers but also market goods, furniture, and even livestock strapped precariously to the frame. Drivers typically owned their own vehicles and worked long hours, often from early morning until well after sunset, since fares were modest and a full day's pedaling was needed to earn a reasonable income.", "That central role began to fade after the economic reforms of the late 1980s opened the country to faster growth. Motorbikes became affordable to ordinary households, and they could carry passengers more quickly across distances that once took a cyclo driver considerable effort to cover. City authorities in Hanoi restricted cyclos from a growing number of central streets in the early 2000s, citing traffic congestion, and similar rules soon followed in Ho Chi Minh City. Within a decade, the number of registered cyclos in both cities had fallen by more than half, and many former drivers switched to driving motorbike taxis instead.", "Cyclos have not disappeared entirely, however. In tourist districts such as Hanoi's Old Quarter and the ancient town of Hoi An, they now function chiefly as a way for visitors to see the sights at a gentle pace, with drivers doubling as informal tour guides who point out temples, markets, and colonial buildings along the route. This shift toward tourism has kept a small fleet of cyclos in business, though the drivers themselves are ageing, and few young workers are willing to take up a trade that pays little and demands considerable physical stamina.", "Recognizing what would be lost if the cyclo vanished altogether, several municipal tourism boards have begun small programs to register drivers, standardize fares, and promote cyclo tours as part of the local heritage experience. Whether these measures will be enough to keep the tradition alive remains uncertain, but for now the cyclo continues to occupy a modest, if shrinking, place in the rhythm of Vietnamese city life."], questions: [{ q: "What is the main idea of the passage?", options: ["The cyclo shifted from everyday transport into a tourist role.", "The cyclo has vanished entirely because of modern motorized transport.", "Cyclos declined mainly because motorbikes became cheaper and faster.", "Tourism created the cyclo, replacing its original transport function entirely."], answer: 0 }, { q: "According to the passage, when did the cyclo first appear in Vietnam?", options: ["Sometime after Hanoi and Saigon grew into major cities.", "During the 1930s, under French colonial administration.", "In the early 2000s, when traffic rules changed.", "During the 1980s, following the country's economic reforms."], answer: 1 }, { q: "According to the passage, besides passengers, what did families sometimes transport by cyclo?", options: ["Building materials, farm tools, and small motorbikes for repair.", "Market goods, furniture, and other passengers riding for free.", "Livestock, furniture, and drivers' personal belongings for trips.", "Market goods, furniture, and livestock tied to the frame."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a factor in the cyclo's decline?", options: ["City authorities restricted cyclos from many central streets.", "Many drivers switched to driving motorbike taxis instead.", "A shortage of spare parts made repairs increasingly difficult.", "Motorbikes became affordable to ordinary households across Vietnam."], answer: 2 }, { q: "The word \"precariously\" in paragraph 2 is closest in meaning to _______.", options: ["commercially", "unsteadily", "securely", "previously"], answer: 1 }, { q: "The word \"This\" in paragraph 4 refers to _______.", options: ["temples and markets", "informal tour guides", "colonial buildings", "cyclos' tourist role"], answer: 3 }, { q: "The word \"novelty\" in paragraph 2 is closest in meaning to _______.", options: ["a business", "a novel", "something unusual", "a luxury"], answer: 2 }, { q: "What can be inferred from the passage about the future of the cyclo?", options: ["Preservation programs began because ageing drivers reduced tourist interest.", "Whether cyclos survive depends on current preservation efforts succeeding.", "Cyclos will certainly disappear once tourism programs end soon.", "Cyclos have already vanished from everyday urban commuting entirely."], answer: 1 }, { q: "According to the passage, where do cyclos mainly operate today?", options: ["In Hanoi's traffic-restricted streets near the city's main markets.", "In rural villages where motorbikes are still too expensive.", "In tourist districts such as Hanoi's Old Quarter and Hoi An.", "In central Ho Chi Minh City's newly built business district."], answer: 2 }, { q: "What is the author's overall attitude toward the cyclo's changing role?", options: ["Confident that cyclos will remain common for many years.", "Sympathetic, viewing the cyclo as valuable heritage worth preserving.", "Strongly critical of government traffic policies in past decades.", "Purely technical, focused only on how cyclos are built."], answer: 1 }] },
    { title: "Teaching Young Children to Brush Their Teeth", paragraphs: ["Although a child's first teeth are eventually replaced, the habits formed while caring for them may shape oral health for decades to come. Dental researchers have increasingly turned their attention to early childhood, once considered a lower priority than adult dental care, because the habits established before age six appear to persist, for better or worse, well into adulthood. Some evidence suggests that children who begin supervised brushing before their second birthday develop fewer cavities in their permanent teeth later on, though the causal mechanism remains only partially understood.", "Most dental associations recommend that a parent or caregiver handle the brushing directly until a child is about three years old, then gradually shift to supervised self-brushing rather than switching abruptly to full independence. This gradual approach — often overlooked by busy families — reflects the fact that fine motor skills needed to angle a brush against the gumline develop only slowly, typically not maturing until around age six or seven. Even children who insist they can brush unaided often miss the inner surfaces of the back teeth, the very spot where cavities most commonly form.", "Fluoride toothpaste is generally advised from the appearance of the first tooth, though the amount matters more than many parents assume. A smear no larger than a grain of rice is typically recommended for children under three, expanding only to a pea-sized amount once a child reliably spits rather than swallows. Swallowing excess fluoride during the years when adult teeth are still forming underneath the gums can, in some cases, lead to faint white markings on the teeth later, a condition dentists call fluorosis, though most cases are mild and largely cosmetic.", "Because resistance at the sink is one of the most common obstacles caregivers report, many pediatric dentists now argue that the emotional tone of brushing time matters as much as the technique itself. Songs, timers shaped like sand-glasses, and letting a child brush a stuffed animal's teeth first have each been shown, in small studies, to reduce the daily struggle, even though none of these strategies improves the mechanical thoroughness of the brushing on its own.", "When these early habits fail to take hold, the consequences extend well beyond the baby teeth themselves. Early childhood caries, a rapid and severe form of decay linked to prolonged bottle use and inconsistent brushing, can cause pain intense enough to interfere with eating and, in turn, with a child's growth. Because the underlying permanent teeth sit so close beneath the baby teeth, untreated infection can occasionally damage the enamel of teeth that have not yet even emerged, connecting the neglect of a temporary tooth to a lifelong mark on a permanent one.", "Pediatric dentists generally recommend a first dental visit by a child's first birthday, a schedule that surprises many parents who assume visits should wait until several teeth, or all of them, have emerged. This early visit is intended less to treat existing problems than to let a dentist check technique, discuss fluoride use, and catch the earliest signs of decay before they progress into the more serious complications described above."], questions: [{ q: "What is the main idea of the passage?", options: ["Dental visits before age one prevent all future tooth decay.", "Fluoride toothpaste alone determines whether children develop healthy teeth.", "Early brushing habits and parental guidance influence lifelong dental health.", "Parents alone determine whether a child avoids tooth decay."], answer: 2 }, { q: "According to the passage, how much toothpaste is typically recommended for a child under three?", options: ["No toothpaste at all until the child turns three.", "A smear no bigger than a single grain of rice.", "A full toothbrush head of paste for effective cleaning.", "A pea-sized amount, once the child can spit reliably."], answer: 1 }, { q: "According to the passage, when do pediatric dentists generally recommend a child's first dental visit?", options: ["After several teeth or all of them have emerged.", "Only once a child begins showing signs of decay.", "By the time a child turns one year old.", "Around age six or seven, when motor skills mature."], answer: 2 }, { q: "According to the passage, at what age do children typically develop the fine motor skills needed to brush effectively on their own?", options: ["Around two years old, their second birthday.", "Around three years old, when caregivers stop brushing.", "Around six or seven years old.", "Around one year old, at the first dental visit."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a strategy to make brushing time easier for children?", options: ["Using an hourglass-shaped timer for absolutely every session.", "Letting a child brush a stuffed animal's teeth first.", "Singing songs during a child's brushing time.", "Rewarding children with sugary treats after brushing sessions."], answer: 3 }, { q: "The word \"unaided\" in paragraph 2 is closest in meaning to _______.", options: ["unaware", "on their own", "carelessly", "without fluoride"], answer: 1 }, { q: "The word \"prolonged\" in paragraph 5 is closest in meaning to _______.", options: ["reduced", "prolific", "flavored", "extended"], answer: 3 }, { q: "The word \"these\" in paragraph 5 refers to _______.", options: ["sand-glass timers", "bottle use", "early oral hygiene routines", "stuffed animals"], answer: 2 }, { q: "What can be inferred from the passage about the relationship between baby teeth and permanent teeth?", options: ["Untreated decay always causes permanent teeth to fall out.", "Infections in baby teeth can sometimes damage developing permanent teeth.", "Problems in developing permanent teeth cause decay in baby teeth.", "Baby teeth are always eventually replaced by permanent teeth."], answer: 1 }, { q: "What is the author's overall purpose in this passage?", options: ["To inform parents about evidence-based hygiene practices for children.", "To warn parents specifically about the dangers of fluorosis.", "To criticize parents who let children brush without help.", "To argue dental visits matter more than daily brushing."], answer: 0 }] },
    { title: "Reality Television and the Regulation of Children's Programming in Australia", paragraphs: ["Long before Australian streaming platforms existed, free-to-air broadcasters were required to reserve a proportion of daytime programming for content classified specifically for children, a system that shaped, for nearly half a century, what an entire generation watched during weekday afternoons. Introduced in the 1970s, the so-called C-classification imposed quotas on locally produced drama and limited how much imported material commercial networks could substitute for local production, a compromise between protecting children's interests and satisfying broadcasters' commercial pressures. Whether this arrangement actually improved what children watched, rather than merely determining who produced it, remains a question the system's original architects seem never to have fully resolved.", "Reality television, largely absent from children's schedules through most of the classification system's history, entered this protected space only once producers realized that unscripted formats could be made cheaply enough to satisfy local-content quotas without matching the production costs of drama. Family-oriented competition formats, some borrowed from adult prime-time franchises and simply reformatted with younger contestants, began appearing on children's timeslots from the early 2000s onward. Because these formats technically qualified as local content despite requiring far less scripting and rehearsal than traditional children's drama, networks found in them an economically convenient way of meeting their quota obligations while quietly reducing what critics call genuine investment in children's programming.", "Researchers who have examined the shift are divided on what it means for young viewers. Some studies suggest that competition-based formats may model persistence and teamwork in ways conventional drama rarely does explicitly, since contestants' setbacks and recoveries are shown in real time rather than compressed into a scripted resolution. Other researchers argue that the same real-time exposure, stripped of a drama's narrative safeguards, risks presenting elimination and public judgment as ordinary features of childhood achievement, a framing that some hold responsible — though the evidence here remains preliminary — for the modest rise in appearance-related anxiety researchers have recorded among frequent child viewers of these formats .", "Because regulators have historically classified content by production origin and format rather than by psychological impact, reality formats featuring child contestants have continued to satisfy local-content requirements even as concerns about their effects have grown. The regulator responsible for content classification reviewed its guidelines in the mid-2010s, yet ultimately concluded that existing quotas, designed for an era of scripted drama, required no formal amendment to accommodate a genre its original drafters had never anticipated.", "In the absence of stronger regulation, several networks have introduced their own safeguards, including delayed broadcast times that allow parents to preview episodes and voluntary limits on the number of elimination-style formats broadcast within any single season. Whether these voluntary measures substitute adequately for the regulatory oversight applied to scripted children's drama is a question industry executives answer more confidently than the researchers who study the programming's effects.", "Australia's approach differs from that of several comparable broadcasting markets, where reality formats aimed at children face additional restrictions specifically tied to competitive elimination rather than to local-content origin, restrictions Australian regulators have so far declined to adopt on the grounds that they would apply unevenly across formats that resemble competition television only superficially.", "What emerges from this history is less a settled verdict than an unresolved tension between a quota system built to protect local production and a genre whose psychological effects the system was never designed to evaluate. Until Australian regulators revisit the classification framework itself, rather than simply the formats it happens to admit, the debate over reality television's place in children's programming seems likely to continue without clear resolution."], questions: [{ q: "What is the main idea of the passage?", options: ["Australia's classification system rewards drama financially over unscripted formats.", "Australia's classification system was designed to eliminate reality programming entirely.", "Australia's classification system already resolved concerns about reality programming's effects.", "Australia's classification system has not adapted to address reality format concerns."], answer: 3 }, { q: "According to the passage, when was the C-classification system introduced?", options: ["In the early 2000s, when reality formats began appearing.", "In the mid-2010s, when regulators reviewed their guidelines.", "Sometime after streaming platforms became widely available in Australia.", "In the 1970s, decades before reality formats appeared."], answer: 3 }, { q: "According to the passage, why were reality formats able to satisfy local-content quotas despite concerns about their effects?", options: ["Because international broadcasters pressured Australian regulators to loosen the quotas.", "Because parents voluntarily requested more competition-based programming for children.", "Because researchers found no evidence that reality formats affected children at all.", "Because regulators classified content by origin and format, not psychological effect."], answer: 3 }, { q: "According to the passage, what voluntary safeguard have some networks introduced?", options: ["Mandatory psychological screening for all child contestants before filming.", "Delayed broadcast times that let parents preview episodes beforehand.", "A complete ban on elimination-style formats for young audiences.", "Government-mandated limits on the number of reality formats broadcast."], answer: 1 }, { q: "According to the passage, which of the following is NOT presented as a feature of the local-content quota system?", options: ["Quotas limited how much imported material could replace local production.", "The system was reviewed and revised specifically to regulate reality formats' effects.", "The system dates back to before reality television existed on children's schedules.", "The classification imposed requirements on locally produced drama content."], answer: 1 }, { q: "The word \"compromise\" in paragraph 1 is closest in meaning to _______.", options: ["a trade-off", "a promise", "a failure", "a broadcast schedule"], answer: 0 }, { q: "The word \"preliminary\" in paragraph 3 is closest in meaning to _______.", options: ["financially limited", "completely false", "not yet conclusive", "primary"], answer: 2 }, { q: "The phrase \"these formats\" in paragraph 3 refers to _______.", options: ["scripted resolutions", "competition-based formats", "conventional drama", "narrative safeguards"], answer: 1 }, { q: "What can be inferred from the passage about the mid-2010s regulatory review?", options: ["Regulators avoided any review because reality formats caused no measurable harm.", "The regulator left quotas unchanged despite reviewing guidelines for an unanticipated genre.", "The review concluded reality formats needed no changes since they caused no harm.", "The classification system was introduced in the 1970s to regulate drama."], answer: 1 }, { q: "What is the author's overall purpose in this passage?", options: ["To present an unresolved tension between quota rules and reality formats' effects.", "To strongly condemn regulators for negligence in protecting children.", "To criticize Australian networks specifically for cutting production costs.", "To argue that reality formats are more educational than scripted drama."], answer: 0 }] },
    { title: "Giant Penguins of the Distant Past: What the Fossil Record Can and Cannot Tell Us", paragraphs: ["Not until the early twenty-first century did paleontologists fully appreciate how large some of the earliest penguins actually grew, despite fossil fragments having been catalogued in New Zealand collections for decades beforehand. Renewed analysis of bones long dismissed as belonging to marine reptiles revealed instead an extinct penguin lineage whose largest members may have stood as tall as an adult human and weighed considerably more than any living species, findings that prompted a broader reassessment of just how quickly penguins, following the extinction of large marine reptiles, expanded into the ecological space those predators had vacated.", "Because the fossils in question date to within roughly ten million years of the mass extinction event that eliminated marine reptiles and non-avian dinosaurs alike, some researchers argue that penguins may have exploited a newly emptied predatory niche with unusual speed, though others caution that the fossil record from this period remains too sparse to distinguish rapid opportunistic expansion from a slower diversification that merely appears compressed given how few specimens have survived. Comparable uncertainty affects related debates about how quickly other post-extinction lineages diversified, since preservation bias — the tendency for larger, more robust bones to survive intact more often than delicate skeletal elements — can itself distort apparent patterns of early size and abundance.", "Whatever pace of expansion eventually proves accurate, the skeletal evidence itself is comparatively unambiguous: these giant penguins possessed proportionally longer and more robust flipper bones than their modern relatives, a structural difference researchers interpret as evidence of adaptation for sustained deep diving rather than merely fast, shallow pursuit of prey near the surface.", "This inference concerning diving capacity is not derived directly from soft-tissue evidence, which fossilizes only under exceptional circumstances, but rather from comparative analysis of bone density and flipper proportion against living diving birds; such comparative reasoning, while broadly accepted within the field, necessarily carries greater uncertainty than a direct anatomical observation would, since it depends on the assumption that equivalent skeletal structures serve equivalent functions across tens of millions of years of separate evolution.", "Later fossil penguins, appearing in deposits tens of millions of years younger than the giant early forms, show a consistent reduction in average body size, a pattern some paleontologists tentatively attribute to the emergence of large marine mammals as competing or predatory pressures, though this explanation remains one of several competing hypotheses rather than an established consensus, since the timing of marine mammal diversification does not align precisely with the size decline in every regional fossil sequence examined so far.", "Any claim linking penguin body size directly to a single environmental cause should therefore be read with some caution, not because the underlying skeletal measurements are in dispute, but because attributing a multi-million-year trend to any one factor risks understating how many overlapping pressures — climatic, competitive, and nutritional — could plausibly have acted on these populations simultaneously, several of which leave no distinguishable trace in the fossil record at all. Some of the strongest published claims in this area rely on statistical inference from small sample sizes, a limitation the original researchers themselves generally acknowledge more explicitly than subsequent popular summaries of their work tend to.", "What the fossil evidence permits, at present, is a reasonably confident account of what these early penguins looked like and roughly how they moved through water, paired with a far less certain account of why their descendants grew smaller — a gap between descriptive confidence and causal explanation that is likely to persist until substantially more specimens, ideally from a wider range of geological periods and locations, are recovered and analyzed."], questions: [{ q: "What is the main idea of the passage?", options: ["Fossil evidence describes giant penguins well, though why they shrank stays uncertain.", "Fossil evidence confirms marine reptiles directly caused early penguins to grow larger.", "Fossil evidence indicates climate change alone caused early penguins to shrink.", "Fossil evidence proves conclusively that marine mammals caused penguins to shrink."], answer: 0 }, { q: "According to the passage, what had these giant penguin fossils originally been believed to be, before renewed analysis?", options: ["Bones belonging to non-avian dinosaurs.", "Bones belonging to a separate, smaller penguin species.", "Bones belonging to marine reptiles.", "Bones belonging to large marine mammals."], answer: 2 }, { q: "According to the passage, why is the claim about deep-diving ability considered less certain than a direct anatomical observation would be?", options: ["Because living diving birds evolved their flippers independently of any penguin lineage.", "Because soft-tissue evidence directly contradicts the bone density measurements taken.", "Because it depends on comparing skeletal structures across tens of millions of years of separate evolution.", "Because researchers have found no flipper bones preserved in the fossil record."], answer: 2 }, { q: "According to the passage, what explanation do some paleontologists tentatively offer for the later size decline in penguins?", options: ["A confirmed shift in ocean temperature during the same geological period.", "A well-established increase in marine reptile populations during this era.", "A definitively proven decline in available prey across all regions studied.", "The emergence of large marine mammals as competing or predatory pressures."], answer: 3 }, { q: "According to the passage, which of the following is NOT presented as a factor potentially contributing to changes in penguin body size over time?", options: ["Climatic pressures acting on penguin populations over millions of years.", "A sudden volcanic event eliminating penguin nesting sites entirely.", "Competitive pressures from other marine species.", "Nutritional pressures affecting penguin populations over time."], answer: 1 }, { q: "The word \"sparse\" in paragraph 2 is closest in meaning to _______.", options: ["sparing", "scarce", "expensive", "outdated"], answer: 1 }, { q: "The word \"robust\" in paragraph 3 is closest in meaning to _______.", options: ["flexible", "robotic", "sturdy", "buoyant"], answer: 2 }, { q: "The phrase \"This inference\" at the beginning of paragraph 4 refers to _______.", options: ["shallow pursuit of prey", "modern penguin relatives", "the claim about deep-diving adaptation", "flipper bone fossilization rates"], answer: 2 }, { q: "What can be inferred from the passage about the relationship between preservation bias and scientific conclusions about early penguins?", options: ["Preservation bias proves that all giant penguin fossils are misclassified marine reptiles.", "Preservation bias has no effect on conclusions since only bones are studied.", "Preservation bias makes it certain that early penguins were smaller than currently believed.", "Preservation bias may distort apparent patterns of early penguin size and abundance."], answer: 3 }, { q: "How does the author primarily structure the argument in this passage?", options: ["By refuting all previous research on early penguin evolution entirely.", "By arguing definitively that marine mammals caused the size decline in penguins.", "By presenting confident anatomical findings alongside increasingly hedged causal claims.", "By treating the size-decline explanation as equally certain as the anatomical findings."], answer: 2 }] },
  ] },
];
